        event=event, email='dummy@example.org', status=Order.STATUS_PAID, datetime=now(), expires=now(),
        total=Decimal('23.00'), code='MEMB2', customer=customer,
        sales_channel=event.organizer.sales_channels.get(identifier="web"),
    )
    OrderPosition.objects.create(
        order=order, item=requiring_ticket, price=23, positionid=1, used_membership=membership,
    )
    p = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [p], event)


@pytest.mark.django_db
def test_validate_memberships_non_transferable_other_attendee(event, customer, membership, requiring_ticket, membership_type):
    membership_type.transferable = False
    membership_type.save()
    membership.attendee_name_parts = {'_scheme': 'full', 'full_name': 'John Doe'}
    membership.save()
    p = _cart_position(event, requiring_ticket, membership, attendee_name_parts={'_scheme': 'full', 'full_name': 'Jane Doe'})
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [p], event)
    p.attendee_name_parts = {'_scheme': 'full', 'full_name': 'John Doe'}
    validate_memberships_in_order(customer, [p], event)
